export function transform(PD) { // Sample Event Transformation let body = PD.inputRequest.body; let zdxLinkURL = body.zdxUrl; let emitEv = true; let ruleName = body.ruleName; if (ruleName.toLowerCase() == "test") emitEv = false; let payloadCount = "

"; if ( body.status == "STARTED" ) { payloadCount += "Affected: 
Geolocations: " + body.geolocationCount + "
Departments: " + body.deptCount + "
Impacted Devices: " + body.impactedDeviceCount + "
OS Versions: " + body.osverCount } let normalized_event = { event_action: PD.Trigger, // optionally include a key to prevent creating duplicate // incidents when the same event is sent more than once // dedup_key: body.event_key, payload: { summary: `Rule: ${body.ruleName}, Severity: ${body.severity} ${body.status}`, source: 'ZDX', severity: PD.Critical, custom_details: `AlertId: ${body.alertId}
Rule Name: ${body.ruleName}
Severity: ${body.severity}
Criteria: ${body.criteriaString}
Link: ${zdxLinkURL} ${payloadCount}` }, dedup_key: "", // optionally display links or images on web and mobile links: [{ "href": zdxLinkURL, "text": "Alert Details" }], }; if ( emitEv) PD.emitEventsV2([normalized_event]); }
